#include "freshness.hpp"

#include &lt;cmath&gt;
#include &lt;cstdlib&gt;
#include &lt;exception&gt;
#include &lt;iostream&gt;
#include &lt;string&gt;
#include &lt;vector&gt;

namespace {

constexpr double tolerance = 1e-12;

void require(bool condition, const std::string& message)
{
    if (!condition) {
        std::cerr &lt;&lt; "FAIL: " &lt;&lt; message &lt;&lt; '\n';
        std::exit(1);
    }
}

void require_near(double actual, double expected, const std::string& message)
{
    require(std::abs(actual - expected) &lt;= tolerance, message);
}

template &lt;typename Function&gt;
void require_invalid_argument(Function function, const std::string& message)
{
    try {
        function();
    } catch (const std::invalid_argument&) {
        return;
    }

    require(false, message);
}

void test_age_uses_effect_time()
{
    require_near(
        temporal::age_at_effect(12.25, 13.00),
        0.75,
        "age must be measured at effect time");
}

void test_snapshot_uses_oldest_sample_and_full_skew()
{
    const std::vector&lt;double&gt; sample_times{12.4, 11.8, 12.1};
    const auto result = temporal::evaluate_snapshot(
        sample_times, 13.0, 1.2, 0.6);

    require_near(result.oldest_age, 1.2, "oldest field determines absolute age");
    require_near(result.relative_skew, 0.6, "max-minus-min determines relative skew");
    require(result.age_valid, "absolute-age boundary must be inclusive");
    require(result.skew_valid, "relative-skew boundary must be inclusive");
}

void test_effect_delay_can_invalidate_freshness()
{
    const std::vector&lt;double&gt; sample_times{12.4, 11.8, 12.1};
    const auto result = temporal::evaluate_snapshot(
        sample_times, 13.000000000001, 1.2, 0.6);

    require_near(
        result.oldest_age,
        1.200000000001,
        "effect delay must remain in the measured age");
    require(!result.age_valid, "age beyond the inclusive boundary must fail");
    require(result.skew_valid, "effect delay must not alter relative skew");
}

void test_ctmc_transition_probability()
{
    require_near(
        temporal::up_to_down_probability(0.2, 0.3, 0.0),
        0.0,
        "zero horizon must have zero transition probability");
    require_near(
        temporal::up_to_down_probability(0.2, 0.3, 4.0),
        0.3458658867053549,
        "nominal CTMC transition probability must match the hand calculation");
    require_near(
        temporal::up_to_down_probability(1.0, 3.0, 0.5),
        0.2161661791908468,
        "asymmetric CTMC rates must use their sum in the exponent");
    require_near(
        temporal::up_to_down_probability(0.0, 0.7, 5.0),
        0.0,
        "zero failure rate must produce zero failure probability");
}

void test_invalid_domains_are_rejected()
{
    require_invalid_argument(
        [] { temporal::age_at_effect(2.0, 1.0); },
        "an effect before its sample must be rejected");
    require_invalid_argument(
        [] { temporal::evaluate_snapshot({}, 1.0, 1.0, 1.0); },
        "an empty snapshot must be rejected");
    require_invalid_argument(
        [] { temporal::up_to_down_probability(-1.0, 1.0, 1.0); },
        "negative CTMC rates must be rejected");
    require_invalid_argument(
        [] { temporal::up_to_down_probability(0.0, 0.0, 1.0); },
        "a CTMC with no transitions must be rejected");
}

}  // namespace

int main()
{
    test_age_uses_effect_time();
    test_snapshot_uses_oldest_sample_and_full_skew();
    test_effect_delay_can_invalidate_freshness();
    test_ctmc_transition_probability();
    test_invalid_domains_are_rejected();

    std::cout &lt;&lt; "PASS freshness equations\n";
    return 0;
}

